def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        if opp.get('budget', 0) >= 140:
            rich_opp_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    remaining_days = max(1, 10 - int(day) + 1)
    reserve_target = max(0.0, remaining_days * 18.0)
    spendable = max(0.0, budget - reserve_target)

    base = 20.0 + 18.0 * scarcity

    if highest_prev >= 150:
        pressure_bid = highest_prev + 1.25
    elif highest_prev >= 120:
        pressure_bid = highest_prev + 1.75
    elif highest_prev >= 80:
        pressure_bid = max(65.0, avg_prev + 4.0)
    else:
        pressure_bid = max(38.0, avg_prev + 3.0)

    bid = base

    if supply >= 22 and danger == 0:
        bid = min(bid, 24.0)
    elif supply >= 20 and danger <= 1:
        bid = max(bid, 28.0)
    elif supply <= 17:
        bid = max(bid, pressure_bid)
    elif supply <= 19:
        bid = max(bid, 0.75 * pressure_bid)

    if urgent_opp_count >= 2 and supply <= 18:
        bid = max(bid, pressure_bid + 2.0)
    elif rich_opp_count >= 2 and supply <= 17:
        bid = max(bid, pressure_bid + 1.0)

    if danger >= 5:
        bid = max(bid, highest_prev + 2.5, 118.0)
    elif danger >= 3:
        bid = max(bid, highest_prev + 1.5, 88.0)
    elif danger >= 1:
        bid = max(bid, 52.0)

    if spendable < bid and danger == 0:
        bid = max(16.0, min(spendable + 10.0, 42.0))
    elif spendable < bid and danger <= 2:
        bid = min(budget, max(45.0, spendable + 18.0))

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        bid = min(bid, 26.0)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opps.append((opp_id, opp))
        except Exception:
            pass

    # If no opponents alive, conserve water
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else 0.0

    # Supply-based urgency: with 15-25 supply, each unit of water is valuable.
    # If supply is high, lower bids may still win.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base target bid: aim slightly above what strong opponents likely paid yesterday.
    # But avoid matching their full aggression unless we are in danger.
    # Use hp/no_water_days to decide whether to escalate.
    danger = 0
    if hp <= 2.0:
        danger = 2
    elif hp <= 4.0:
        danger = 1

    if no_water_days >= 2:
        danger = max(danger, 1)

    # Estimate a competitive threshold
    # If yesterday highest was very high, strong players are spending.
    # We counter with a moderate overbid; otherwise bid around a fraction of highest.
    if highest_prev_bid >= DAILY_SALARY * 1.0:  # ~90
        if danger >= 2:
            target = highest_prev_bid * 0.75 + 5.0
        elif danger == 1:
            target = highest_prev_bid * 0.55 + 3.0
        else:
            target = highest_prev_bid * 0.45 + 2.0
    else:
        if danger >= 2:
            target = max(DAILY_SALARY * 0.7, second_prev_bid * 0.8 + 2.0)
        elif danger == 1:
            target = max(DAILY_SALARY * 0.55, second_prev_bid * 0.6 + 2.0)
        else:
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.35 + 2.0)

    # Adjust for supply: higher supply => reduce bid pressure
    target = target * (1.0 - 0.15 * supply_ratio)

    # Clamp by budget and avoid overpaying near end-game
    # If late day, increase slightly.
    if day >= 8:
        target *= 1.08

    # Ensure non-negative
    target = max(0.0, target)

    # Final bid: never exceed budget
    bid = min(budget, target)

    # If budget is too low, bid whatever remains (still non-negative)
    if bid < 0.0:
        bid = 0.0

    return float(bid)

