        max_prev = max(yesterday_bids)
        if day_context['supply'] < 18:
            return min(my_status['budget'], max_prev + 2.0)
        return min(my_status['budget'], max(30.0, max_prev * 0.6))

    return min(my_status['budget'], 45.0)
